7	export async function loadMarkdownSources(root: string, directoryName: string): Promise<readonly SourceMarkdownFile[]> {
8	  const sourceRoot = path.join(root, directoryName);
9	  const files = await listFiles(sourceRoot, (filePath) => filePath.endsWith(".md"));
10	  const sources = await Promise.all(files.map(loadMarkdownSource));
11	  return sources.sort((left, right) => left.name.localeCompare(right.name));
12	}
13	
14	export async function loadSkillSources(root: string): Promise<readonly SourceSkill[]> {
15	  const skillsRoot = path.join(root, "skills");
16	  const skillFiles = await listFiles(
17	    skillsRoot,
18	    (filePath) => path.basename(filePath) === "SKILL.md" && !hasHiddenPathSegment(skillsRoot, filePath),
19	  );
20	  const skills = await Promise.all(skillFiles.map(loadSkillSource));
21	  return skills.sort((left, right) => left.name.localeCompare(right.name));
22	}
