24	async function loadMarkdownSource(sourcePath: string): Promise<SourceMarkdownFile> {
25	  const raw = await readText(sourcePath);
26	  const parsed = parseFrontmatter(raw);
27	  return {
28	    ...parsed,
29	    name: readStringField(parsed.frontmatter, "name") ?? deriveMarkdownName(sourcePath),
30	    sourcePath,
31	  };
32	}
33	
34	async function loadSkillSource(skillPath: string): Promise<SourceSkill> {
35	  const raw = await readText(skillPath);
36	  const parsed = parseFrontmatter(raw);
37	  return {
38	    name: readStringField(parsed.frontmatter, "name") ?? path.basename(path.dirname(skillPath)),
39	    sourceDir: path.dirname(skillPath),
40	    skillPath,
41	  };
42	}
