=CONTRACT=
You are one reviewer in a multi-model code-review ensemble. You are given a
changeset (the diff plus the list of changed files) and exactly ONE review pass
to perform. Other models run the other passes, so stay in your lane.

Read each changed file in full for context. Use the diff to distinguish introduced
lines from pre-existing code. Only flag issues **introduced or affected by this
changeset**; do not flag pre-existing issues unless a changed line directly
interacts with them. Rank by severity, highest first.

Severity:
- **must**: correctness, security (will break or is unsafe)
- **should**: performance, traceability, conventions (should be fixed)
- **nit**: style, naming, and **questions** (trivially ignorable)

Questions vs findings: a claim earns **should/must** only when you back it with a
concrete failure scenario (specific inputs traced to the wrong output) or a
demonstrated need for the code. An unproven suspicion, or a bare "why is this hunk
here?" motivation query, is a **question**: keep it, but emit it at `nit` severity
so the author can answer or dismiss it, never should/must. `confidence` is
orthogonal to this split: it reports how sure you are the observation is real and
introduced, so a question you are certain names an unexplained hunk still scores
high (do not deflate it, or the confidence floor drops it). The verifier refutes
speculation with no concrete failure path, so a should/must lacking a scenario will
be culled regardless: ground it or downgrade it to a question yourself.

Be specific: cite the exact file and line and the concrete problem, e.g.
"`linear.py:87`: `resp.json()` called on network errors; move it inside the
success branch". Never be vague ("error handling could be better"). No praise, no
filler, no restating the code.

Write plainly. Do NOT use em-dashes (-) in any claim or rationale; use a colon, a
comma, parentheses, or a separate sentence instead. Keep each claim to one line.

## Output contract
Return ONLY a JSON object: no prose, no markdown fences, nothing else.

{"findings": [{"file": "path/to/file", "line": 0, "severity": "must|should|nit",
"category": "<this pass's name>", "claim": "<one-line problem>", "rationale":
"<why it breaks, what the impact is>", "confidence": 0.0}]}

`confidence` is your 0.0 to 1.0 certainty the issue is real and introduced. If
there are no issues for your pass, return exactly {"findings": []}.

def dedup(findings: list[dict]) -> list[dict]:
    seen: dict[tuple, dict] = {}
    out = []
    for f in findings:
        k = key(f)
        if k in seen:
            sources = finding_sources(seen[k]) + finding_sources(f)
            seen[k]["_by"] = sorted(set(sources))
            if SEV.get(f["severity"], 2) < SEV.get(seen[k]["severity"], 2):
                seen[k]["severity"] = f["severity"]
            continue
        seen[k] = f
        out.append(f)
    return out


def verify(tier: str, findings: list[dict], diff: str, files: list[str]) -> list[dict]:
    if not findings:
        return []
    panel = stage_models(tier, "refute")
    voters = (panel * ((REFUTE_VOTES // len(panel)) + 1))[:REFUTE_VOTES]
    # One batched refutation per voter (each judges every finding by id), mirroring
    # arbitrate. This keeps REFUTE_VOTES independent votes while cutting calls from
    # findings×voters to just len(voters), the dominant runtime win.
    fields = ("id", "file", "line", "severity", "category", "claim", "rationale")
    payload = json.dumps([{k: f.get(k) for k in fields} for f in findings])
    prompt = changeset_context(diff, files) + "\n\n## Findings\n" + payload
    prompt += "\n\n" + load("refute.md")
    tasks = [((vi,), fam, model, prompt, REFUTE_SCHEMA, exploration_effort(tier))
             for vi, (fam, model) in enumerate(voters)]
    results = parallel(tasks, "verify")
    # Tally refute votes per finding. A failed voter contributes no refutes, so
    # infra failures never lower the bar (a finding can only be dropped by a
    # planned-voter majority actively refuting it).
    refutes = {f["id"]: 0 for f in findings}
    for vi in range(len(voters)):
        res = results.get((vi,))
        if not res:
            continue
        for v in res.get("verdicts", []):
            if v.get("refuted") and v.get("id") in refutes:
                refutes[v["id"]] += 1
    survivors = [f for f in findings if refutes[f["id"]] <= len(voters) / 2]
    log(f"verify: {len(survivors)}/{len(findings)} survive refutation")
    return survivors


def arbitrate(tier: str, findings: list[dict], diff: str, files: list[str]) -> tuple[list[dict], list[str]]:
    if not findings:
        return [], []
    fields = ("id", "file", "line", "severity", "category", "claim", "rationale")
    payload = json.dumps([{k: f.get(k) for k in fields} for f in findings])
    prompt = changeset_context(diff, files) + "\n\n## Findings\n" + payload
    prompt += "\n\n" + load("arbitrate.md")
    panel = stage_models(tier, "arbitrate")
    tasks = [((fam,), fam, model, prompt, ARB_SCHEMA, "high")
             for fam, model in panel]
    results = parallel(tasks, "arbitrate")

    by_id = {f["id"]: f for f in findings}
    decisions: dict[str, dict] = {}
    hotspots: list[str] = []
    for res in results.values():
        if not res:
            continue
        for d in res.get("decisions", []):
            fid = d.get("id")
            if fid not in by_id:
                continue
            sev = d.get("severity", by_id[fid]["severity"])
            cur = decisions.get(fid)
            if cur is None:
                decisions[fid] = {"keep": bool(d.get("keep", True)), "severity": sev}
            else:
                # Union keep (recall-biased); most-severe label wins.
                cur["keep"] = cur["keep"] or bool(d.get("keep", True))
                if SEV.get(sev, 2) < SEV.get(cur["severity"], 2):
                    cur["severity"] = sev
        for h in res.get("hotspots", []):
            if h and h not in hotspots:
                hotspots.append(h)

    kept = []
    for f in findings:
        dec = decisions.get(f["id"])
        if dec is None or dec["keep"]:  # unjudged findings survive (conservative)
            if dec:
                f["severity"] = dec["severity"]
            kept.append(f)
    log(f"arbitrate: {len(kept)}/{len(findings)} kept, {len(hotspots)} hotspots")
    return kept, hotspots[:5]


def broaden_loop(tier, passes, base, files, claude_md, kept, hotspots):
    seen = {key(f) for f in kept}
    rounds = 0
    while hotspots and rounds < MAX_BROADEN_ROUNDS:
        rounds += 1
        hot = [f for f in files if any(h in f or f in h for h in hotspots)] or files
        hot_diff = diff_text(base, hot)
        fresh = [f for f in find(tier, passes, hot_diff, hot, claude_md) if key(f) not in seen]
        fresh = dedup(fresh)
        if not fresh:
            log(f"broaden round {rounds}: nothing new, converged")
            break

