#!/usr/bin/env python3
"""Merge tp-super-review finder artifacts: confidence floor -> dedupe -> ids.

Mirrors review.py: confident() (floor 0.3, missing counts as confident),
dedup() (key = file, line, normalized claim[:60]; most-severe wins; _by union).
"""
import glob
import json
import re
import uuid

CONFIDENCE_FLOOR = 0.3
SEV = {"must": 0, "should": 1, "nit": 2}


def key(f):
    claim = re.sub(r"\W+", " ", (f.get("claim") or "").lower()).strip()
    return (f.get("file"), f.get("line"), claim[:60])


def main():
    merged, dropped_lowconf, bad = [], 0, []
    for path in sorted(glob.glob("/tmp/orca-review-find-*.json")):
        src = path.split("orca-review-find-")[1].removesuffix(".json")
        try:
            data = json.load(open(path))
        except Exception as e:  # noqa: BLE001
            bad.append(f"{path}: {e}")
            continue
        for f in data.get("findings", []):
            c = f.get("confidence")
            try:
                if c is not None and float(c) < CONFIDENCE_FLOOR:
                    dropped_lowconf += 1
                    continue
            except (TypeError, ValueError):
                pass  # unparseable counts as confident (fail-open)
            f["_by"] = [src]
            merged.append(f)

    seen, out = {}, []
    for f in merged:
        k = key(f)
        if k in seen:
            seen[k]["_by"] = sorted(set(seen[k]["_by"] + f["_by"]))
            if SEV.get(f.get("severity"), 2) < SEV.get(seen[k].get("severity"), 2):
                seen[k]["severity"] = f["severity"]
            continue
        f["id"] = uuid.uuid4().hex[:12]
        seen[k] = f
        out.append(f)

    json.dump({"findings": out}, open("/tmp/orca-review-candidates.json", "w"), indent=1)
    by_sev = {}
    for f in out:
        by_sev[f.get("severity", "?")] = by_sev.get(f.get("severity", "?"), 0) + 1
    print(f"artifacts merged; raw={len(merged) + dropped_lowconf} lowconf_dropped={dropped_lowconf} deduped={len(out)} by_sev={by_sev}")
    for f in out:
        print(f"  [{f['id']}] {f.get('severity')} {f.get('file')}:{f.get('line')} ({','.join(f['_by'])}) {f.get('claim','')[:90]}")
    if bad:
        print("BAD ARTIFACTS:", *bad, sep="\n  ")


if __name__ == "__main__":
    main()

